package com.driveflow.servlet;
import com.driveflow.model.*; import com.driveflow.store.DataStore; import com.driveflow.util.Flash; import javax.servlet.*; import javax.servlet.http.*; import java.io.IOException; import java.time.LocalDate;
public class RentalServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if("return".equals(req.getParameter("action"))){try{Rental r=DataStore.rental(Integer.parseInt(req.getParameter("id")));if(r==null||r.getStatus()!=Rental.Status.ACTIVE)throw new IllegalArgumentException("Active rental not found.");r.setStatus(Rental.Status.RETURNED);r.setReturnDate(LocalDate.now());Vehicle v=DataStore.vehicle(r.getVehicleId());if(v!=null)v.setStatus(Vehicle.Status.AVAILABLE);Flash.set(req.getSession(),"success","Vehicle returned successfully.");}catch(Exception e){Flash.set(req.getSession(),"error",e.getMessage());}resp.sendRedirect(req.getContextPath()+"/rentals");return;}req.setAttribute("rentals",DataStore.rentals);req.setAttribute("vehicles",DataStore.vehicles);req.setAttribute("customers",DataStore.customers);req.getRequestDispatcher("/views/rentals.jsp").forward(req,resp);}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{try{int vid=Integer.parseInt(req.getParameter("vehicleId")),cid=Integer.parseInt(req.getParameter("customerId"));Vehicle v=DataStore.vehicle(vid);if(v==null||v.getStatus()!=Vehicle.Status.AVAILABLE)throw new IllegalArgumentException("Selected vehicle is not available.");LocalDate start=LocalDate.parse(req.getParameter("startDate")),end=LocalDate.parse(req.getParameter("endDate"));if(end.isBefore(start))throw new IllegalArgumentException("End date must be on or after start date.");long days=Math.max(1,java.time.temporal.ChronoUnit.DAYS.between(start,end));double total=days*v.getDailyRate();Rental r=new Rental(DataStore.nextRentalId(),vid,cid,start,end,total,Rental.Status.ACTIVE);DataStore.rentals.add(r);v.setStatus(Vehicle.Status.RENTED);Flash.set(req.getSession(),"success","Rental #"+r.getId()+" created. Total: ₹"+String.format("%.2f",total));}catch(Exception e){Flash.set(req.getSession(),"error","Could not create rental: "+e.getMessage());}resp.sendRedirect(req.getContextPath()+"/rentals");}
}
